+                node.from,
+                node.to,
+                Decoration.widget({
+                  widget: new ObjectWidget(props),
+                }),
+              );
+            }
+            break;
+          }
+
+          case QueryDSL.Node.And:
+          case QueryDSL.Node.Or: {
+            atomicDeco.add(
+              node.from,
+              node.to,
+              Decoration.mark({
+                class: 'pie-1',
+              }),
+            );
+            break;
+          }
+
+          case QueryDSL.Node.ArrowRight:
+          case QueryDSL.Node.ArrowLeft: {
+            deco.add(
