+    return { deco: deco.finish(), atomicDeco: atomicDeco.finish() };
+  };
+
+  return [
+    StateField.define<{ deco: DecorationSet; atomicDeco: DecorationSet }>({
+      create: (state) => buildDecorations(state),
+      update: (deco, tr) => {
