+        }
+        const data = line.slice(dataPrefix.length).trim();
+        if (data === '[DONE]') {
+          return { done: true };
+        }
+        const chunk = JSON.parse(data) as OpenAiStreamChunk;
+        const choice = chunk.choices?.[0];
+        return {
+          content: choice?.delta?.content,
+          done: choice?.finish_reason !== null,
+        };
+      }
+    }
+  } catch {
+    return null;
+  }
+};
