+      const p = db.add(Obj.make(TestSchema.Person, { name: 'Parent' }));
+      const c = db.add(Obj.make(TestSchema.Person, { name: 'Child' }));
+
+      Obj.setParent(p, gp);
+      Obj.setParent(c, p);
+
+      childId = c.id;
+      await db.flush();
+    }
+
+    await peer.reload();
+
+    {
+      await using db = await peer.openLastDatabase();
+      // We query ONLY for the child.
