+        return nil;
+    });
+    
+    Method method = class_getInstanceMethod(wkContentViewClass, originalSelector);
+    if (method) {
+        method_setImplementation(method, nilImp);
+        NSLog(@"[KeyboardHandler] Input Accessory View disabled");
+    }

