+        maxPolarAngle={Math.PI / 2}
+        minDistance={2}
+        maxDistance={gridSize * 3}
+      />
+      <GizmoHelper alignment='bottom-right' margin={[60, 60]}>
+        <GizmoViewport />
+      </GizmoHelper>
+    </>
