+    ...parseVoxelKey(key),
+    hue: props.hue,
+  }));
+};
+
+/** Convert an array of VoxelData to a voxel map. */
+export const toVoxelMap = (voxels: VoxelData[]): VoxelMap => {
+  const map: VoxelMap = {};
