+   */
+  readonly #spaceCache = new Map<CacheKey, CachedInstance>();
+
+  /**
+   * Process-level cache (reference counted, lives until all resolvers are closed).
+   */
+  readonly #processCache = new Map<CacheKey, CachedInstance>();
+
+  #destroyed = false;
