+          'x-api-key': apiKey,
+          'anthropic-version': '2023-06-01',
+        },
+        body: JSON.stringify({
+          model: 'claude-sonnet-4-20250514',
+          max_tokens: 500,
+          stream: true,
+          system: systemPrompt,
+          messages: conversationMessages,
+        }),
