+                  size={2.5}
+                  classNames='text-description'
+                />
+              )}
+            </button>
+
+            {/* Expanded detail panel. */}
+            {expanded && expandable && (
+              <div className='ml-5 mr-1 my-0.5 p-2 rounded-sm bg-input/50 border border-separator text-[11px] font-mono overflow-x-auto'>
+                {step.toolInput && (
