+    const newSteps: InspectorStep[] = [];
+
+    for (const message of newMessages) {
+      for (const event of message.events) {
+        const step = normalizeEvent(event, message);
+        if (step) {
+          newSteps.push(step);
+        }
+      }
+    }
+
+    if (newSteps.length > 0) {
+      setSteps((prev) => [...prev, ...newSteps]);
+    }
+  }, [traceMessages]);
