+ * Returns true if the value is a valid DXN in the new `dxn:<nsid>[:<version>]` format.
+ * Does not accept the legacy `dxn:<kind>:<...>` format.
+ */
+export const isDXN = (s: unknown): s is DXN => typeof s === 'string' && DXN_SPEC_REGEXP.test(s);
+
+/**
