+ * echo://BA25QRC2FEWCSAMRP4RZL65LWJ7352CKE/01J00J9B45YHYSGZQTQMSKMGJ6
+ * echo:/01J00J9B45YHYSGZQTQMSKMGJ6
+ * echo://BA25QRC2FEWCSAMRP4RZL65LWJ7352CKE
+ * ```
+ */
