+    const nodeA: LayoutNode = { id: 'a' };
+    host.hit = { kind: 'node', node: nodeA };
+    target.dispatchEvent(ev(0, 0));
+
+    expect(events).toEqual(['hover-enter:a']);
+
+    detach();
+  });
