+): SegmentValues => {
+  const segments: SegmentValues = {};
+  if (options.dateOrder) {
+    segments.yyyy = pad(date.getFullYear(), 4);
+    segments.MM = pad(date.getMonth() + 1, 2);
+    segments.dd = pad(date.getDate(), 2);
+  }
+  if (options.timeOrder) {
