+export class Vec2 {
+  x: number;
+  y: number;
+  active = false;
+
+  constructor(x = 0, y = 0) {
+    this.x = x;
+    this.y = y;
+  }
+
+  add(v: Vec2): this {
+    this.x += v.x;
+    this.y += v.y;
+    return this;
+  }
+
+  subtract(v: Vec2): this {
+    this.x -= v.x;
+    this.y -= v.y;
+    return this;
+  }
+
+  scale(s: number): this {
+    this.x *= s;
+    this.y *= s;
+    return this;
+  }
+
+  scaleTo(s: number): this {
+    const length = this.length();
+    this.x = (this.x * s) / length;
+    this.y = (this.y * s) / length;
+    return this;
+  }
+
+  normalize(): this {
+    const length = this.length();
+    this.x /= length;
+    this.y /= length;
+    return this;
