+  const trailer = [
+    `**Type:** ${values.type}`,
+    `**Severity:** ${values.severity}`,
+    values.area && `**Area:** ${values.area}`,
+    values.version && `**Version:** ${values.version}`,
+  ]
+    .filter(Boolean)
+    .join('\n');
+
+  const body = [screenshotUrl && `![Screenshot](${screenshotUrl})`, values.body, '---', trailer]
+    .filter(Boolean)
