+  // from labels); needs to match a configured type name on the org. See the
+  // ISSUE_TYPE_NAME table above.
+  const params = new URLSearchParams({
+    title: values.title,
+    body,
+    labels: labels.join(','),
+    type: ISSUE_TYPE_NAME[values.type],
+  });
