+  const request: InvokeRequest = {
+    version: 1,
+    id: nextId(),
+    actionId: action.id,
+    page: { url: tab.url ?? '', title: tab.title ?? '' },
+    inputs,
+    invokedFrom: 'popup',
+  };
+  return deliverInvoke(request);
+};

