+  const minuteNum = parseInt(minute);
+  if (hourlyMatch && dom === '*' && month === '*' && dow === '*' && !isNaN(minuteNum)) {
+    return { frequency: 'hourly', interval: parseInt(hourlyMatch[1]), minute: minuteNum };
+  }
