+export const extractProperNouns = (text: string): string[] => {
+  const matches = text.match(/\b[A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+)*\b/g) ?? [];
+  return Array.from(new Set(matches.filter((word) => !STOP_WORDS.has(word))));
