+    .filter((noun) => !matched.has(noun.toLowerCase()))
+    .map((noun) => {
+      const start = Math.max(0, text.indexOf(noun));
+      return { text: noun, kind: 'proper-noun' as const, start, end: start + noun.length };
+    });
