+const stubExtractor = (opts: {
+  onExtract?: (message: Message.Message) => Effect.Effect<ExtractResult, ExtractError>;
+}): ObjectExtractor => ({
+  id: EXTRACTOR_ID,
+  title: EXTRACTOR_ID,
