+    void runDebugPortLoop({
+      session,
+      origin,
+      evalCommand: makeEvalCommand(scope),
+      onLog: log,
+      signal: abort.signal,
+    })
+      .catch((error) => {
+        if (!abort.signal.aborted) {
+          log(`Debug port error: ${error instanceof Error ? error.message : String(error)}`);
+        }
+      })
