+  const response = await fetch(path, {
+    method: 'POST',
+    headers: { 'content-type': 'application/json' },
+    body: JSON.stringify({ prompt, cwd, maxTurns, resume, fork }),
+    signal,
+  });
+  if (!response.ok || !response.body) {
+    throw new Error(`agent host responded ${response.status}`);
+  }
