+      }
+      return TITLE_H + node.children.reduce((sum, child) => sum + heightOf(child) + GAP, 0) + PAD;
+    case 'array':
+      return TITLE_H + heightOf(node.item) + GAP + PLUS_H + PAD;
+    case 'form':
+      return (
