+  const states = new Map<string, Database.SyncState>();
+  const cleanups = new Map<string, () => void>();
+
+  const subscribe = (space: Space) => {
+    if (cleanups.has(space.id)) {
+      return;
+    }
+
+    try {
+      cleanups.set(
+        space.id,
+        space.db.subscribeToSyncState((state) => {
+          states.set(space.id, state);
+        }),
+      );
+    } catch (err) {
