+  const parseExpr = (): number => {
+    let value = parseTerm();
+    while (peek() === '+' || peek() === '-') {
+      const op = input[position++];
+      const rhs = parseTerm();
+      value = op === '+' ? value + rhs : value - rhs;
+    }
+    return value;
+  };
+
+  // term := factor (('*' | '/') factor)*
+  const parseTerm = (): number => {
+    let value = parseFactor();
