+  for (const name of ['@automerge/automerge', '@automerge/automerge-subduction']) {
+    const resolved = resolver.sync(from, `${name}/slim`);
+    if (!resolved.error && resolved.path) {
+      aliases[name] = resolved.path;
+    }
+  }
+  return aliases;
+};

