+};
+
+//
+// State
+//
+
+/**
+ * Context state.
+ */
+const widgetContextStateField = StateField.define<any>({
+  create: () => undefined,
+  update: (value, tr) => {
+    for (const effect of tr.effects) {
+      if (effect.is(widgetContextEffect)) {
