+      const state = withCurrentWidgetState(rawState);
+      const isNew = !widgets.has(state.id);
+      widgets.set(state.id, state);
+      // Only a genuinely new id changes the portal set (blank-frame culprit); re-parents just re-notify.
+      if (debug && isNew) {
