+  tree.iterate({
+    from: range.from,
+    to: range.to,
+    enter: (node) => {
+      const claimants = matchers.filter((matcher) => matcher.nodes.includes(node.type.name));
+      if (claimants.length === 0) {
+        return;
+      }
