+      for (const matcher of claimants) {
+        try {
+          const match = matcher.match(node, ctx);
+          if (match) {
+            builder.add(match.from, match.to, match.decoration);
+            // Track last widget (NOTE: range is inclusive).
+            last = match.to - 1;
