+          }
+          const [source = fetchFromGitHub] = capabilities.getAll(GitHubCapabilities.LinkSource);
+          const object = yield* source(link, context);
+          return object && { label: Issue.reference(object), object };
+        }),
+    ]);
+  }),
+);
