+const WORKER_URL = /https:\/\/[a-z0-9-]+\.[a-z0-9-]+\.workers\.dev(?:\/[\w./-]*)?/gi;
+const CLAIM_URL = /https:\/\/dash\.cloudflare\.com\/claim/i;
