+};
+
+/** What a set of samples for one tool came to. */
+export type Stats = {
+  readonly count: number;
+  readonly errors: number;
+  readonly min: number;
+  readonly mean: number;
+  readonly p50: number;
+  readonly p95: number;
+  readonly max: number;
+};
