+  const emit = RuntimeProvider.runPromise(runtime);
+
+  return {
+    createIdentity: async (params = {}, ctx = defaultCtx) => {
+      const identity = await identityManager.createIdentity(params, ctx);
+      await emit(EffectEvent.emit(IdentityBound, { identity }));
